window.AUTH=window.AUTH||{};window.AUTH["18-801"]={"d":"18-801","id":"2019/18-801","n":"Peter v. NantKwest, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioner Laura Peter, Deputy Director, Patent and Trademark Office,","date":"2019-05-17","url":"https://www.supremecourt.gov/DocketPDF/18/18-801/100233/20190517154547195_18-801tsUnitedStates.pdf","side":"pet","n":97},{"k":"respondent","label":"Brief of respondent NantKwest, Inc.","date":"2019-07-15","url":"https://www.supremecourt.gov/DocketPDF/18/18-801/108155/20190715180203785_18-801bs.pdf","side":"res","n":100},{"k":"reply","label":"Reply of petitioner Laura Peter, Deputy Director, Patent and Trademark Office","date":"2019-08-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-801/112313/20190814125603386_18-801rbUnitedStates.pdf","side":"pet","n":40}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/589US1PP_Web.pdf#page=64","tr":true,"items":[{"t":"case","label":"Alyeska Pipeline Serv. Co. v. Wilderness Soc’y","cite":"421 U.S. 240","y":1975,"id":"1974/73-1977","sc":1,"op":3,"ar":2,"sum":"Under the \"American Rule\" that attorneys' fees are not ordinarily recoverable by the prevailing litigant in federal litigation in the absence of statutory authorization, respondents, which had instituted litigation to prevent issuance of Government permits required for construction of the trans-Alaska oil pipeline, cannot recover attorneys' fees from petitioner based on the \"private attorney general\" approach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","1":"passim","2":"15"}},{"t":"case","label":"Arlington Cent. Sch. Dist. Bd. of Educ. v. Murphy","cite":"548 U.S. 291","y":2006,"id":"2005/05-18","sc":1,"op":1,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that IDEA did not authorize reimbursement of expert fees. \"While authorizing the award of reasonable attorney's fees, the Act contains detailed provisions that are designed to ensure that such awards are indeed reasonable,\" Justice Alito wrote. \"The absence of any comparable provisions relating to expert fees strongly suggests that recovery of expert fees is not authorized.\" Justice Alito went on to write that the case was made even simpler by the fact that, as an exercise of Congress's Spending Clause power, any provision requiring reimbursement of expert fees would have had to be \"unambiguous,\" which it clearly was not.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"B & B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Baker Botts L.L.P. v. ASARCO LLC","cite":"135 S. Ct. 2158","y":2015,"id":"2014/14-103","sc":1,"op":5,"ar":2,"sum":"The Court held that the Bankruptcy Code does not provide an explicit statutory exception to the American rule of attorney fees—that each litigant pays for his own attorney’s fees.","sumSrc":"Oyez","by":{"0":"10, 32, 33, 34, 38, 39","1":"passim","2":"15, 20"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Bilski v. Kappos","cite":"561 U.S. 593","y":2010,"id":"2009/08-964","sc":1,"sum":"The Court held that the \"machine-or-transformation\" test adopted by the Patent and Trademark Office (PTO) was a legal means for determining patent eligibility.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"BP Am. Prod. Co. v. Burton","cite":"549 U.S. 84","y":2006,"id":"2006/05-669","sc":1,"sum":"The Court ruled 7-0 that \"the 6-year statute of limitations in 2415(a) applies only to court actions and not to the administrative proceedings involved in this case.\" The opinion by Justice Samuel Alito relied on the plain meaning of the language in Section 2415(a). The statute used the terms \"action\" and \"complaint\" when referring to the statute of limitations.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Cook v. Watson","cite":"208 F.2d 529","y":1953,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/208/529/","by":{"0":"7","1":"2, 24, 24"}},{"t":"case","label":"Crawford Fitting Co. v. J. T. Gibbons, Inc.","cite":"482 U.S. 437","y":1987,"id":"1986/86-322","sc":1,"sum":"When a prevailing party seeks reimbursement for fees paid to its expert witnesses, a federal court is bound by the limits of § 1821(b), absent contract or explicit statutory authority to the contrary. There is no merit to petitioners' contentions that, since § 1920 lists expenses which a court \"may\" tax as costs, it only authorizes taxation of such items and does not preclude taxation for other items or amounts in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","1":"3"}},{"t":"case","label":"Dickinson v. Zurko","cite":"527 U.S. 150","y":1999,"id":"1998/98-377","sc":1,"sum":"The Court held that the Court of Appeals for the Federal Circuit must use the framework set forth in the Administrative Procedure Act when reviewing PTO findings of fact.","sumSrc":"Oyez","by":{"0":"3, 25","2":"8"}},{"t":"case","label":"Dome Patent, L.P. v. Rea","cite":"59 F. Supp. 3d 52","y":2014,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/59/52/","by":{"0":"25"}},{"t":"case","label":"Gandy v. Marble","cite":"122 U.S. 432","y":1887,"id":"scdb/1886-292","sc":1,"sum":"On a bill in equity filed under § 4915 of the Revised Statutes, to obtain an adjudication in favor of the grautrag of a patent, the plaintiff must allege and prove that a delay of two years and more in prosecuting the application after the last action therein of which notice was given to him was unavoidable, or the application will be regarded as having been abandoned, within the provision of § 4894.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30, 35, 39","1":"50, 51","2":"12"}},{"t":"case","label":"Hardt v. Reliance Standard Life Ins. Co.","cite":"560 U.S. 242","y":2010,"id":"2009/09-448","sc":1,"op":3,"sum":"The Court held that a party is entitled to attorneys' fees pursuant to Section 502(g)(1) of the Employee Retirement Income Security Act when an ERISA violation has occurred.","sumSrc":"Oyez","by":{"0":"33, 34, 36, 39","1":"passim","2":"17"}},{"t":"case","label":"Hoover Co. v. Coe","cite":"325 U.S. 79","y":1945,"id":"scdb/1944-150","sc":1,"sum":"1. A federal district court has jurisdiction of a suit under R. S. § 4915 to review a decision of the Board of Appeals of the Patent Office rejecting a claim as not reading on the disclosure in the application for a patent. Pp. 80, 83. Jurisdiction is not defeated by the fact that an adjudication favorable to the applicant might not conclude all possible qu.estions as to the applicant's right to a patent.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 5"}},{"t":"case","label":"Hutchinson ex rel. Julien v. Patrick","cite":"636 F.3d 1","y":2011,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/636/1/","sum":"Explaining that counsel’s “travel expenses” may be “incorporated as part of a fee award”.","sumSrc":"brief:0","by":{"0":"31"}},{"t":"case","label":"Hutto v. Finney","cite":"437 U.S. 678","y":1978,"id":"1977/76-1660","sc":1,"sum":"The Court held that punitive isolation for longer than thirty days in Arkansas prisons constituted cruel and unusual punishment and violated the Constitution. Justice Stevens conceded that isolation in and of itself was not necessarily unconstitutional and may in fact serve an important, legitimate interest in administering a prison.","sumSrc":"Oyez","by":{"0":"20","1":"43"}},{"t":"case","label":"Hyatt v. Kappos","cite":"625 F.3d 1320","y":2010,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/625/1320/","by":{"0":"4, 28 ,35","1":"48","2":"15"}},{"t":"case","label":"Kappos v. Hyatt","cite":"566 U.S. 431","y":2012,"id":"2011/10-1219","sc":1,"op":3,"sum":"The Court held that a patent applicant's ability to introduce new evidence in a civil action against the Patent and Trademark Office was only limited by the Federal Rules of Evidence and the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"0":"3, 4, 25","1":"2, 48, 49","2":"9"}},{"t":"case","label":"Key Tronic Corp. v. United States","cite":"511 U.S. 809","y":1994,"id":"1993/93-376","sc":1,"op":1,"sum":"CERCLA § 107 does not provide for the award of private litigants' attorney's fees associated with bringing a cost recovery action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","1":"31, 37, 49","2":"18, 19, 20"}},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"sum":"The Court found that a bankruptcy court may not enforce specific statutory exceptions.","sumSrc":"Oyez","by":{"0":"20","1":"43"}},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"op":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"NLRB v. Local 3, Int’l Bhd. of Elec. Workers","cite":"471 F.3d 399","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/471/399/","by":{"0":"36"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"572 U.S. 545","y":2014,"id":"2013/12-1184","sc":1,"sum":"A case in which the Court defined \"exceptional\" cases as ones that simply stand out from others due to a frivolous nature related to its legal claims.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Rimini St., Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"op":2,"sum":"A federal district court’s discretion to award “full costs” to a party in copyright litigation pursuant to 17 U. S. C. §505 is limited to the six categories specified in the general costs statute codified at 28 U. S. C. §§1821 and 1920.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 24, 39, 41","1":"passim","2":"7"}},{"t":"case","label":"Robertson v. Cooper","cite":"46 F.2d 766","y":1931,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/46/766/","by":{"0":"7, 31","1":"2, 23, 24, 44, 24, 24","2":"13"}},{"t":"case","label":"Ruckelshaus v. Sierra Club","cite":"463 U.S. 680","y":1983,"id":"1982/82-242","sc":1,"op":2,"sum":"Absent some degree of success on the merits by the claimant, it is not \"appropriate\" for a federal court to award attorney's fees under §307(f).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34, 36, 37","1":"passim"}},{"t":"case","label":"Sandvik Aktiebolag v. Samuels","cite":"20 U.S.P.Q.2d 1879","y":1991,"court":"D.D.C.","url":"https://www.courtlistener.com/c/U.S.P.Q.2d/20/1879/","by":{"0":"7, 41"}},{"t":"case","label":"SD3, LLC v. Lee","cite":"205 F. Supp. 3d 37","y":2016,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/205/37/","by":{"0":"25"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"op":3,"ar":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"0":"17, 37","1":"39, 40","2":"17, 18"}},{"t":"case","label":"Shammas v. Focarino","cite":"784 F.3d 219","y":2015,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/784/219/","sum":"Concluding that Section 1071(b) requires an applicant “to pay, as ‘all the expenses of the proceeding,’ the salaries of the PTO’s attorneys and paralegals attributed to the defense of the action”.","sumSrc":"brief:0","by":{"0":"12, 19, 22, 24, 35","1":"passim","2":"12, 16"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"op":3,"ar":1,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"0":"11, 20, 39","1":"44, 45","2":"4"}},{"t":"case","label":"West Va. Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"op":2,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 40, 42","1":"passim","2":"20, 21"}},{"t":"law","label":"Pub. L. No. 87-772","url":"https://www.govinfo.gov/link/statute/76/771","by":{"0":"6"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"0":"3"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(E)"],"by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 102-166","url":"https://www.govinfo.gov/link/statute/105/1079","by":{"0":"20"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","subs":["(a)"],"by":{"0":"6, 6"}},{"t":"usc","label":"15 U.S.C. § 1071","url":"https://www.law.cornell.edu/uscode/text/15/1071","subs":["(a)(1)","(b)","(b)(1)","(b)(3)"],"stext":{"head":"§1071. Appeal to courts","paras":[[0,"(a) Persons entitled to appeal; United States Court of Appeals for the Federal Circuit; waiver of civil action; election of civil action by adverse party; procedure"],[0,"(1) An applicant for registration of a mark, party to an interference proceeding, party to an opposition proceeding, party to an application to register as a lawful concurrent user, party to a cancellation proceeding, a registrant who has filed an affidavit as provided in section 1058 of this title or section 1141k of this title, an applicant for renewal, or a registrant subject to an ex parte expungement proceeding or an ex parte reexamination proceeding, who is dissatisfied with the decision of the Director or Trademark Trial and Appeal Board, may appeal to the United States Court of Appeals for the Federal Circuit thereby waiving his right to proceed under subsection (b) of this section: Provided, That such appeal shall be dismissed if any adverse party to the proceeding, other than the Director, shall, within twenty days after the appellant has filed notice of appeal according to paragraph (2) of this subsection, files notice with the Director that he elects to have all further proceedings conducted as provided in subsection (b) of this section. Thereupon the appellant shall have thirty days thereafter within which to file a civil action under subsection (b) of this section, in default of which the decision appealed from shall govern the further proceedings in the case."],[0,"(2) When an appeal is taken to the United States Court of Appeals for the Federal Circuit, the appellant shall file in the United States Patent and Trademark Office a written notice of appeal directed to the Director, within such time after the date of the decision from which the appeal is taken as the Director prescribes, but in no case less than 60 days after that date."],[0,"(3) The Director shall transmit to the United States Court of Appeals for the Federal Circuit a certified list of the documents comprising the record in the United States Patent and Trademark Office. The court may request that the Director forward the original or certified copies of such documents during pendency of the appeal. In an ex parte case, the Director shall submit to that court a brief explaining the grounds for the decision of the United States Patent and Trademark Office, addressing all the issues involved in the appeal. The court shall, before hearing an appeal, give notice of the time and place of the hearing to the Director and the parties in the appeal."],[0,"(4) The United States Court of Appeals for the Federal Circuit shall review the decision from which the appeal is taken on the record before the United States Patent and Trademark Office. Upon its determination the court shall issue its mandate and opinion to the Director, which shall be entered of record in the United States Patent and Trademark Office and shall govern the further proceedings in the case. However, no final judgment shall be entered in favor of an applicant under section 1051(b) of this title before the mark is registered, if such applicant cannot prevail without establishing constructive use pursuant to section 1057(c) of this title."],[0,"(b) Civil action; persons entitled to; jurisdiction of court; status of Director; procedure"],[0,"(1) Whenever a person authorized by subsection (a) of this section to appeal to the United States Court of Appeals for the Federal Circuit, except for a registrant subject to an ex parte expungement proceeding or an ex parte reexamination proceeding, is dissatisfied with the decision of the Director or Trademark Trial and Appeal Board, said person may, unless appeal has been taken to said United States Court of Appeals for the Federal Circuit, have remedy by a civil action if commenced within such time after such decision, not less than sixty days, as the Director appoints or as provided in subsection (a) of this section. The court may adjudge that an applicant is entitled to a registration upon the application involved, that a registration involved should be canceled, or such other matter as the issues in the proceeding require, as the facts in the case may appear. Such adjudication shall authorize the Director to take any necessary action, upon compliance with the requirements of law. However, no final judgment shall be entered in favor of an applicant under section 1051(b) of this title before the mark is registered, if such applicant cannot prevail without establishing constructive use pursuant to section 1057(c) of this title."],[0,"(2) The Director shall not be made a party to an inter partes proceeding under this subsection, but he shall be notified of the filing of the complaint by the clerk of the court in which it is filed and shall have the right to intervene in the action."],[0,"(3) In any case where there is no adverse party, a copy of the complaint shall be served on the Director, and, unless the court finds the expenses to be unreasonable, all the expenses of the proceeding shall be paid by the party bringing the case, whether the final decision is in favor of such party or not. In suits brought hereunder, the record in the United States Patent and Trademark Office shall be admitted on motion of any party, upon such terms and conditions as to costs, expenses, and the further cross-examination of the witnesses as the court imposes, without prejudice to the right of any party to take further testimony. The testimony and exhibits of the record in the United States Patent and Trademark Office, when admitted, shall have the same effect as if originally taken and produced in the suit."],[0,"(4) Where there is an adverse party, such suit may be instituted against the party in interest as shown by the records of the United States Patent and Trademark Office at the time of the decision complained of, but any party in interest may become a party to the action. If there are adverse parties residing in a plurality of districts not embraced within the same State, or an adverse party residing in a foreign country, the United States District Court for the Eastern District of Virginia shall have jurisdiction and may issue summons against the adverse parties directed to the marshal of any district in which any adverse party resides. Summons against adverse parties residing in foreign countries may be served by publication or otherwise as the court directs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1071?type=usc&year=mostrecent&link-type=html"},"head":"§1071. Appeal to courts","tname":"Commerce and Trade","by":{"0":"27, 27, 27, 27","1":"passim, 4","2":"2"}},{"t":"usc","label":"42 U.S.C. § 300aa-10","url":"https://www.law.cornell.edu/uscode/text/42/300aa-10","by":{"0":"37"}},{"t":"usc","label":"42 U.S.C. § 300aa-11","url":"https://www.law.cornell.edu/uscode/text/42/300aa-11","by":{"0":"37","1":"39"}},{"t":"usc","label":"42 U.S.C. § 300aa-15","url":"https://www.law.cornell.edu/uscode/text/42/300aa-15","subs":["(e)(1)","(e)"],"by":{"0":"37","1":"39, 39, 40"}},{"t":"law","label":"Pub. L. No. 115-273","url":"https://www.govinfo.gov/link/plaw/115/public/273","by":{"0":"7"}},{"t":"usc","label":"5 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/5/504","subs":["(a)(1)"],"stext":{"head":"§504. Costs and fees of parties","paras":[[0,"(a)(1) An agency that conducts an adversary adjudication shall award, to a prevailing party other than the United States, fees and other expenses incurred by that party in connection with that proceeding, unless the adjudicative officer of the agency finds that the position of the agency was substantially justified or that special circumstances make an award unjust. Whether or not the position of the agency was substantially justified shall be determined on the basis of the administrative record, as a whole, which is made in the adversary adjudication for which fees and other expenses are sought."],[0,"(2) A party seeking an award of fees and other expenses shall, within thirty days of a final disposition in the adversary adjudication, submit to the agency an application which shows that the party is a prevailing party and is eligible to receive an award under this section, and the amount sought, including an itemized statement from any attorney, agent, or expert witness representing or appearing in behalf of the party stating the actual time expended and the rate at which fees and other expenses were computed. The party shall also allege that the position of the agency was not substantially justified. When the United States appeals the underlying merits of an adversary adjudication, no decision on an application for fees and other expenses in connection with that adversary adjudication shall be made under this section until a final and unreviewable decision is rendered by the court on the appeal or until the underlying merits of the case have been finally determined pursuant to the appeal."],[0,"(3) The adjudicative officer of the agency may reduce the amount to be awarded, or deny an award, to the extent that the party during the course of the proceedings engaged in conduct which unduly and unreasonably protracted the final resolution of the matter in controversy. The decision of the adjudicative officer of the agency under this section shall be made a part of the record containing the final decision of the agency and shall include written findings and conclusions and the reason or basis therefor. The decision of the agency on the application for fees and other expenses shall be the final administrative decision under this section."],[0,"(4) If, in an adversary adjudication arising from an agency action to enforce a party's compliance with a statutory or regulatory requirement, the demand by the agency is substantially in excess of the decision of the adjudicative officer and is unreasonable when compared with such decision, under the facts and circumstances of the case, the adjudicative officer shall award to the party the fees and other expenses related to defending against the excessive demand, unless the party has committed a willful violation of law or otherwise acted in bad faith, or special circumstances make an award unjust. Fees and expenses awarded under this paragraph shall be paid only as a consequence of appropriations provided in advance."],[0,"(b)(1) For the purposes of this section—"],[1,"(A) \"fees and other expenses\" includes the reasonable expenses of expert witnesses, the reasonable cost of any study, analysis, engineering report, test, or project which is found by the agency to be necessary for the preparation of the party's case, and reasonable attorney or agent fees (The amount of fees awarded under this section shall be based upon prevailing market rates for the kind and quality of the services furnished, except that (i) no expert witness shall be compensated at a rate in excess of the highest rate of compensation for expert witnesses paid by the agency involved, and (ii) attorney or agent fees shall not be awarded in excess of $125 per hour unless the agency determines by regulation that an increase in the cost of living or a special factor, such as the limited availability of qualified attorneys or agents for the proceedings involved, justifies a higher fee.);"],[1,"(B) \"party\" means a party, as defined in section 551(3) of this title, who is (i) an individual whose net worth did not exceed $2,000,000 at the time the adversary adjudication was initiated, or (ii) any owner of an unincorporated business, or any partnership, corporation, association, unit of local government, or organization, the net worth of which did not exceed $7,000,000 at the time the adversary adjudication was initiated, and which had not more than 500 employees at the time the adversary adjudication was initiated; except that an organization described in section 501(c)(3) of the Internal Revenue Code of 1986 (26 U.S.C. 501(c)(3)) exempt from taxation under section 501(a) of such Code, or a cooperative association as defined in section 15(a) of the Agricultural Marketing Act (12 U.S.C. 1141j(a)), may be a party regardless of the net worth of such organization or cooperative association or for purposes of subsection (a)(4), a small entity as defined in section 601;"],[1,"(C) \"adversary adjudication\" means (i) an adjudication under section 554 of this title in which the position of the United States is represented by counsel or otherwise, but excludes an adjudication for the purpose of establishing or fixing a rate or for the purpose of granting or renewing a license, (ii) any appeal of a decision made pursuant to section 7103 of title 41 before an agency board of contract appeals as provided in section 7105 of title 41, (iii) any hearing conducted under chapter 38 of title 31, and (iv) the Religious Freedom Restoration Act of 1993;"],[1,"(D) \"adjudicative officer\" means the deciding official, without regard to whether the official is designated as an administrative law judge, a hearing officer or examiner, or otherwise, who presided at the adversary adjudication;"],[1,"(E) \"position of the agency\" means, in addition to the position taken by the agency in the adversary adjudication, the action or failure to act by the agency upon which the adversary adjudication is based; except that fees and other expenses may not be awarded to a party for any portion of the adversary adjudication in which the party has unreasonably protracted the proceedings; and"],[1,"(F) \"demand\" means the express demand of the agency which led to the adversary adjudication, but does not include a recitation by the agency of the maximum statutory penalty (i) in the administrative complaint, or (ii) elsewhere when accompanied by an express demand for a lesser amount."],[0,"(2) Except as otherwise provided in paragraph (1), the definitions provided in section 551 of this title apply to this section."],[0,"(c)(1) After consultation with the Chairman of the Administrative Conference of the United States, each agency shall by rule establish uniform procedures for the submission and consideration of applications for an award of fees and other expenses. If a court reviews the underlying decision of the adversary adjudication, an award for fees and other expenses may be made only pursuant to section 2412(d)(3) of title 28."],[0,"(2) If a party other than the United States is dissatisfied with a determination of fees and other expenses made under subsection (a), that party may, within 30 days after the determination is made, appeal the determination to the court of the United States having jurisdiction to review the merits of the underlying decision of the agency adversary adjudication. The court's determination on any appeal heard under this paragraph shall be based solely on the factual record made before the agency. The court may modify the determination of fees and other expenses only if the court finds that the failure to make an award of fees and other expenses, or the calculation of the amount of the award, was unsupported by substantial evidence."],[0,"(d) Fees and other expenses awarded under this subsection shall be paid by any agency over which the party prevails from any funds made available to the agency by appropriation or otherwise."],[0,"(e)(1) Not later than March 31 of the first fiscal year beginning after the date of enactment of the John D. Dingell, Jr. Conservation, Management, and Recreation Act, and every fiscal year thereafter, the Chairman of the Administrative Conference of the United States, after consultation with the Chief Counsel for Advocacy of the Small Business Administration, shall submit to Congress and make publicly available online a report on the amount of fees and other expenses awarded during the preceding fiscal year under this section."],[0,"(2) Each report under paragraph (1) shall describe the number, nature, and amount of the awards, the claims involved in the controversy, and any other relevant information that may aid Congress in evaluating the scope and impact of such awards."],[0,"(3)(A) Each report under paragraph (1) shall account for all payments of fees and other expenses awarded under this section that are made pursuant to a settlement agreement, regardless of whether the settlement agreement is sealed or otherwise subject to a nondisclosure provision."],[0,"(B) The disclosure of fees and other expenses required under subparagraph (A) shall not affect any other information that is subject to a nondisclosure provision in a settlement agreement."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/504?type=usc&year=mostrecent&link-type=html"},"head":"§504. Costs and fees of parties","tname":"Government Organization and Employees","by":{"0":"34","1":"18"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","subs":["(a)(4)(E)(i)"],"by":{"0":"34"}},{"t":"usc","label":"5 U.S.C. § 552a","url":"https://www.law.cornell.edu/uscode/text/5/552a","subs":["(g)(2)(B)"],"by":{"0":"34"}},{"t":"usc","label":"5 U.S.C. § 552b","url":"https://www.law.cornell.edu/uscode/text/5/552b","subs":["(i)"],"by":{"0":"34"}},{"t":"usc","label":"7 U.S.C. § 18","url":"https://www.law.cornell.edu/uscode/text/7/18","subs":["(d)(1)"],"by":{"0":"34"}},{"t":"usc","label":"7 U.S.C. § 210","url":"https://www.law.cornell.edu/uscode/text/7/210","by":{"0":"34"}},{"t":"usc","label":"7 U.S.C. § 499g","url":"https://www.law.cornell.edu/uscode/text/7/499g","subs":["(c)"],"by":{"0":"34"}},{"t":"usc","label":"10 U.S.C. § 2409","url":"https://www.law.cornell.edu/uscode/text/10/2409","subs":["(c)(1)(C)"],"by":{"0":"41"}},{"t":"usc","label":"11 U.S.C. § 330","url":"https://www.law.cornell.edu/uscode/text/11/330","subs":["(a)(1)(A)","(a)(1)","(a)(1)(B)"],"stext":{"head":"§330. Compensation of officers","paras":[[0,"(a)(1) After notice to the parties in interest and the United States Trustee and a hearing, and subject to sections 326, 328, and 329, the court may award to a trustee, a consumer privacy ombudsman appointed under section 332, an examiner, an ombudsman appointed under section 333, or a professional person employed under section 327 or 1103—"],[1,"(A) reasonable compensation for actual, necessary services rendered by the trustee, examiner, ombudsman, professional person, or attorney and by any paraprofessional person employed by any such person; and"],[1,"(B) reimbursement for actual, necessary expenses."],[0,"(2) The court may, on its own motion or on the motion of the United States Trustee, the United States Trustee for the District or Region, the trustee for the estate, or any other party in interest, award compensation that is less than the amount of compensation that is requested."],[0,"(3) In determining the amount of reasonable compensation to be awarded to an examiner, trustee under chapter 11, or professional person, the court shall consider the nature, the extent, and the value of such services, taking into account all relevant factors, including—"],[1,"(A) the time spent on such services;"],[1,"(B) the rates charged for such services;"],[1,"(C) whether the services were necessary to the administration of, or beneficial at the time at which the service was rendered toward the completion of, a case under this title;"],[1,"(D) whether the services were performed within a reasonable amount of time commensurate with the complexity, importance, and nature of the problem, issue, or task addressed;"],[1,"(E) with respect to a professional person, whether the person is board certified or otherwise has demonstrated skill and experience in the bankruptcy field; and"],[1,"(F) whether the compensation is reasonable based on the customary compensation charged by comparably skilled practitioners in cases other than cases under this title."],[0,"(4)(A) Except as provided in subparagraph (B), the court shall not allow compensation for—"],[1,"(i) unnecessary duplication of services; or"],[1,"(ii) services that were not—"],[2,"(I) reasonably likely to benefit the debtor's estate; or"],[2,"(II) necessary to the administration of the case."],[0,"(B) In a chapter 12 or chapter 13 case in which the debtor is an individual, the court may allow reasonable compensation to the debtor's attorney for representing the interests of the debtor in connection with the bankruptcy case based on a consideration of the benefit and necessity of such services to the debtor and the other factors set forth in this section."],[0,"(5) The court shall reduce the amount of compensation awarded under this section by the amount of any interim compensation awarded under section 331, and, if the amount of such interim compensation exceeds the amount of compensation awarded under this section, may order the return of the excess to the estate."],[0,"(6) Any compensation awarded for the preparation of a fee application shall be based on the level and skill reasonably required to prepare the application."],[0,"(7) In determining the amount of reasonable compensation to be awarded to a trustee, the court shall treat such compensation as a commission, based on section 326."],[0,"(b)(1) There shall be paid from the filing fee in a case under chapter 7 of this title $45 to the trustee serving in such case, after such trustee's services are rendered."],[0,"(2) The Judicial Conference of the United States—"],[1,"(A) shall prescribe additional fees of the same kind as prescribed under section 1914(b) of title 28; and"],[1,"(B) may prescribe notice of appearance fees and fees charged against distributions in cases under this title;"],[0,"to pay $15 to trustees serving in cases after such trustees' services are rendered. Beginning 1 year after the date of the enactment of the Bankruptcy Reform Act of 1994, such $15 shall be paid in addition to the amount paid under paragraph (1)."],[0,"(c) Unless the court orders otherwise, in a case under chapter 12 or 13 of this title the compensation paid to the trustee serving in the case shall not be less than $5 per month from any distribution under the plan during the administration of the plan."],[0,"(d) In a case in which the United States trustee serves as trustee, the compensation of the trustee under this section shall be paid to the clerk of the bankruptcy court and deposited by the clerk into the United States Trustee System Fund established by section 589a of title 28."],[0,"(e)(1) There is established a fund in the Treasury of the United States, to be known as the \"Chapter 7 Trustee Fund\", which shall be administered by the Director of the Administrative Office of the United States Courts."],[0,"(2) Deposits into the Chapter 7 Trustee Fund under section 589a(f)(1)(C) of title 28 shall be available until expended for the purposes described in paragraph (3)."],[0,"(3) For fiscal years 2021 through 2026, the Chapter 7 Trustee Fund shall be available to pay the trustee serving in a case that is filed under chapter 7 or a case that is converted to a chapter 7 case in the most recent fiscal year (referred to in this subsection as a \"chapter 7 case\") the amount described in paragraph (4) for the chapter 7 case in which the trustee has rendered services."],[0,"(4) The amount described in this paragraph shall be the lesser of—"],[1,"(A) $60; or"],[1,"(B) a pro rata share, for each chapter 7 case, of the fees collected under section 1930(a)(6) of title 28 and deposited to the United States Trustee System Fund under section 589a(f)(1) of title 28, less the amounts specified in section 589a(f)(1)(A) and (B) of title 28."],[0,"(5) The payment received by a trustee under paragraph (3) shall be paid in addition to the amount paid under subsection (b)."],[0,"(6) Not later than September 30, 2021, the Director of the Administrative Office of the United States Courts shall promulgate regulations for the administration of this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/330?type=usc&year=mostrecent&link-type=html"},"head":"§330. Compensation of officers","tname":"Bankruptcy","by":{"0":"38","1":"26, 35, 14, 15"}},{"t":"usc","label":"12 U.S.C. § 1786","url":"https://www.law.cornell.edu/uscode/text/12/1786","subs":["(p)"],"stext":{"head":"§1786. Termination of insured credit union status; cease and desist orders; removal or suspension from office; procedure","paras":[[0,"(a) Termination of insurance"],[0,"(1) Any insured credit union other than a Federal credit union may, upon not less than ninety days' written notice to the Board and upon the affirmative vote of a majority of its members within one year prior to the giving of such notice, terminate its status as an insured credit union."],[0,"(2) Any insured credit union, other than a Federal credit union, which has obtained a new certificate of insurance from a corporation authorized and duly licensed to insure member accounts may upon not less than ninety days' written notice to the Board convert from status as an insured credit union under this chapter: Provided, That at the time of giving notice to the Board the provisions of paragraph (b)(1) of this section are not being invoked against the credit union."],[0,"(b) Unsound condition of credit union; notice to correct condition; hearing; judicial review"],[0,"(1) Whenever, in the opinion of the Board, any insured credit union is engaging or has engaged in unsafe or unsound practices in conducting the business of such credit union, or is in an unsafe or unsound condition to continue operations as an insured credit union, or is violating or has violated an applicable law, rule, regulation, order, or any condition imposed in writing by the Board in connection with any action on any application, notice, or other request by the credit union or institution-affiliated party,, 1 or is violating or has violated any written agreement entered into with the Board, the Board shall serve upon the credit union a statement with respect to such practices or conditions or violations for the purpose of securing the correction thereof. In the case of an insured State-chartered credit union, the Board shall send a copy of such statement to the commission, board, or authority, if any, having supervision of such credit union. Unless such correction shall be made within one hundred and twenty days after service of such statement, or within such shorter period of not less than twenty days after such service as the Board shall require in any case where it determines that the insurance risk with respect to such credit union could be unduly jeopardized by further delay in the correction of such practices or conditions or violations, or as the commission, board, or authority having supervision of such credit union, if any, shall require in the case of an insured State-chartered credit union, the Board, if it shall determine to proceed further, shall give to the credit union not less than thirty days' written notice of its intention to terminate the status of the credit union as an insured credit union. Such notice shall contain a statement of the facts constituting the alleged unsafe and unsound practices or conditions or violations and shall fix a time and place for a hearing thereon. Such hearing shall be fixed for a date not earlier than thirty days nor later than sixty days after service of such notice unless an earlier or a later date is set by the Board at the request of the credit union. Unless the credit union shall appear at the hearing by a duly authorized representative, it shall be deemed to have consented to the termination of its status as an insured credit union. In the event of such consent, or if upon the record made at any such hearing the Board shall find that any unsafe or unsound practice or condition or violation specified in the notice has been established and has not been corrected within the time above-prescribed in which to make such correction, the Board may issue and serve upon the credit union an order terminating its status as an insured credit union on a date subsequent to the date of such finding and subsequent to the expiration of the time specified in the notice."],[0,"(2) Any credit union whose insured status has been terminated by order of the Board under this subsection shall have the right of judicial review of such order only to the same extent as provided for the review of orders under subsection (j) of this section."],[0,"(c) Notice to members of termination of insured status"],[0,"In the event of the termination of a credit union's status as an insured credit union as provided under subsection (a)(1) or (b) of this section, the credit union shall give prompt and reasonable notice to all of its members whose accounts are insured that it has ceased to be an insured credit union. It may include in such notice a statement of the fact that member accounts insured on the effective date of such termination, to the extent not withdrawn, remain insured for one year from the date of such termination, but it shall not further represent itself in any manner as an insured credit union. In the event of failure to give the notice as herein provided to members whose accounts are insured, the Board is authorized to give reasonable notice."],[0,"(d) Continuation of insurance for one year; approval of conversion of status; procedure subsequent to approval; reduction of premium charges"],[0,"(1) After the termination of the insured status of any credit union as provided under subsection (a)(1) or (b) of this section, insurance of its member accounts to the extent that they were insured on the effective date of such termination, less any amounts thereafter withdrawn which reduce the accounts below the amount covered by insurance on the effective date of such termination, shall continue for a period of one year, but no shares issued by the credit union or deposits made after the date of such termination shall be insured by the Board. The credit union shall continue to maintain its deposit with and pay premiums to the Board during such period as in the case of an insured credit union and the Board shall have the right to examine such credit union from time to time during the period during which such insurance continues. Such credit union shall, in all other respects, be subject to the duties and obligations of an insured credit union for the period of one year from the date of such termination. In the event that such credit union shall be closed for liquidation within such period of one year, the Board shall have the same powers and rights with respect to such credit union as in the case of an insured credit union. Notwithstanding the above, when an insured credit union's insured status is terminated and the credit union subsequently obtains comparable insurance coverage from another source, insurance of its accounts by the fund may cease immediately upon the effective date of such comparable coverage by mutual consent of the credit union and the Board."],[0,"(2) No credit union shall convert from status as an insured credit union under this chapter as provided under subsection (a)(2) of this section until the proposition for such conversion has been approved by a majority of all the directors of the credit union, and by affirmative vote of a majority of the members of the credit union who vote on the proposition in a vote in which at least 20 per centum of the total membership of the credit union participates. Following approval by the directors, written notice of the proposition and of the date set for the membership vote shall be delivered in person to each member, or mailed to each member at the address for such member appearing on the records of the credit union, not more than thirty nor less than seven days prior to such date. The membership shall be given the opportunity to vote by mail ballot. If the proposition is approved by the membership, prompt and reasonable notice of insurance conversion shall be given to all members."],[0,"(3) In the event of a conversion of a credit union from status as an insured credit union under this chapter as provided under subsection (a)(2) of this section, premium charges payable under section 1782(c) of this title shall be reduced by an amount proportionate to the number of calendar months for which the converting credit union will no longer be insured under this chapter. As long as a converting credit union remains insured under this chapter, it shall remain subject to all of the provisions of this subchapter."],[0,"(e) Opinion of Board as to unsound condition of credit union; notice of charges; hearing; order to cease and desist; judicial review"],[0,"(1) If, in the opinion of the Board, any insured credit union, credit union which has insured accounts, or any institution-affiliated party is engaging or has engaged, or the Board has reasonable cause to believe that the credit union or any institution-affiliated party is about to engage, in an unsafe or unsound practice in conducting the business of such credit union, or is violating or has violated, or the Board has reasonable cause to believe that the credit union or any institution-affiliated party is about to violate, a law, rule, or regulation, or any condition imposed in writing by the Board in connection with the granting of any application or other request by the credit union or any written agreement entered into with the Board, the Board may issue and serve upon the credit union or such party a notice of charges in respect thereof. The notice shall contain a statement of the facts constituting the alleged violation or violations or the unsafe or unsound practice or practices, and shall fix a time and place at which a hearing will be held to determine whether an order to cease and desist therefrom should issue against the credit union or the institution-affiliated party. Such hearing shall be fixed for a date not earlier than thirty days nor later than sixty days after service of such notice unless an earlier or a later date is set by the Board at the request of any party so served. Unless the party or parties so served shall appear at the hearing by a duly authorized representative, they shall be deemed to have consented to the issuance of the cease-and-desist order. In the event of such consent, or if upon the record made at any such hearing, the Board shall find that any violation or unsafe or unsound practice specified in the notice of charges has been established, the Board may issue and serve upon the credit union or the institution-affiliated party an order to cease and desist from any such violation or practice. Such order may, by provisions which may be mandatory or otherwise, require the credit union or its institution-affiliated parties to cease and desist from the same, and, further, to take affirmative action to correct the conditions resulting from any such violation or practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1786?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1786. Termination of insured credit union status; cease and desist orders; removal or suspension from office; procedure","tname":"Banks and Banking","by":{"0":"40"}},{"t":"usc","label":"12 U.S.C. § 2607","url":"https://www.law.cornell.edu/uscode/text/12/2607","subs":["(d)(5)"],"by":{"0":"34"}},{"t":"usc","label":"12 U.S.C. § 3417","url":"https://www.law.cornell.edu/uscode/text/12/3417","subs":["(a)(4)"],"by":{"0":"34"}},{"t":"usc","label":"12 U.S.C. § 5005","url":"https://www.law.cornell.edu/uscode/text/12/5005","subs":["(b)(2)(B)"],"by":{"0":"40"}},{"t":"usc","label":"15 U.S.C. § 77k","url":"https://www.law.cornell.edu/uscode/text/15/77k","subs":["(e)"],"by":{"0":"34"}},{"t":"usc","label":"15 U.S.C. § 298","url":"https://www.law.cornell.edu/uscode/text/15/298","subs":["(c)"],"by":{"0":"34"}},{"t":"usc","label":"15 U.S.C. § 1640","url":"https://www.law.cornell.edu/uscode/text/15/1640","subs":["(a)(3)"],"by":{"0":"34"}},{"t":"usc","label":"15 U.S.C. § 2310","url":"https://www.law.cornell.edu/uscode/text/15/2310","subs":["(d)(2)"],"by":{"0":"40"}},{"t":"usc","label":"28 U.S.C. § 361","url":"https://www.law.cornell.edu/uscode/text/28/361","stext":{"head":"§361. Reimbursement of expenses","paras":[[0,"Upon the request of a judge whose conduct is the subject of a complaint under this chapter, the judicial council may, if the complaint has been finally dismissed under section 354(a)(1)(B), recommend that the Director of the Administrative Office of the United States Courts award reimbursement, from funds appropriated to the Federal judiciary, for those reasonable expenses, including attorneys' fees, incurred by that judge during the investigation which would not have been incurred but for the requirements of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/361?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§361. Reimbursement of expenses","tname":"Judiciary and Judicial Procedure","by":{"0":"40"}},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","subs":["(a)(4)(C)"],"stext":{"head":"§1295. Jurisdiction of the United States Court of Appeals for the Federal Circuit","paras":[[0,"(a) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from a final decision of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court of the Northern Mariana Islands, in any civil action arising under, or in any civil action in which a party has asserted a compulsory counterclaim arising under, any Act of Congress relating to patents or plant variety protection;"],[1,"(2) of an appeal from a final decision of a district court of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, if the jurisdiction of that court was based, in whole or in part, on section 1346 of this title, except that jurisdiction of an appeal in a case brought in a district court under section 1346(a)(1), 1346(b), 1346(e), or 1346(f) of this title or under section 1346(a)(2) when the claim is founded upon an Act of Congress or a regulation of an executive department providing for internal revenue shall be governed by sections 1291, 1292, and 1294 of this title;"],[1,"(3) of an appeal from a final decision of the United States Court of Federal Claims;"],[1,"(4) of an appeal from a decision of—"],[2,"(A) the Patent Trial and Appeal Board of the United States Patent and Trademark Office with respect to a patent application, derivation proceeding, reexamination, post-grant review, or inter partes review under title 35, at the instance of a party who exercised that party's right to participate in the applicable proceeding before or appeal to the Board, except that an applicant or a party to a derivation proceeding may also have remedy by civil action pursuant to section 145 or 146 of title 35; an appeal under this subparagraph of a decision of the Board with respect to an application or derivation proceeding shall waive the right of such applicant or party to proceed under section 145 or 146 of title 35;"],[2,"(B) the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office or the Trademark Trial and Appeal Board with respect to applications for registration of marks and other proceedings as provided in section 21 of the Trademark Act of 1946 (15 U.S.C. 1071); or"],[2,"(C) a district court to which a case was directed pursuant to section 145, 146, or 154(b) of title 35;"],[1,"(5) of an appeal from a final decision of the United States Court of International Trade;"],[1,"(6) to review the final determinations of the United States International Trade Commission relating to unfair practices in import trade, made under section 337 of the Tariff Act of 1930 (19 U.S.C. 1337);"],[1,"(7) to review, by appeal on questions of law only, findings of the Secretary of Commerce under U.S. note 6 to subchapter X of chapter 98 of the Harmonized Tariff Schedule of the United States (relating to importation of instruments or apparatus);"],[1,"(8) of an appeal under section 71 of the Plant Variety Protection Act (7 U.S.C. 2461);"],[1,"(9) of an appeal from a final order or final decision of the Merit Systems Protection Board, pursuant to sections 7703(b)(1) and 7703(d) of title 5;"],[1,"(10) of an appeal from a final decision of an agency board of contract appeals pursuant to section 7107(a)(1) of title 41;"],[1,"(11) of an appeal under section 211 of the Economic Stabilization Act of 1970;"],[1,"(12) of an appeal under section 5 of the Emergency Petroleum Allocation Act of 1973;"],[1,"(13) of an appeal under section 506(c) of the Natural Gas Policy Act of 1978; and"],[1,"(14) of an appeal under section 523 of the Energy Policy and Conservation Act."],[0,"(b) The head of any executive department or agency may, with the approval of the Attorney General, refer to the Court of Appeals for the Federal Circuit for judicial review any final decision rendered by a board of contract appeals pursuant to the terms of any contract with the United States awarded by that department or agency which the head of such department or agency has concluded is not entitled to finality pursuant to the review standards specified in section 7107(b) of title 41. The head of each executive department or agency shall make any referral under this section within one hundred and twenty days after the receipt of a copy of the final appeal decision."],[0,"(c) The Court of Appeals for the Federal Circuit shall review the matter referred in accordance with the standards specified in section 7107(b) of title 41. The court shall proceed with judicial review on the administrative record made before the board of contract appeals on matters so referred as in other cases pending in such court, shall determine the issue of finality of the appeal decision, and shall, if appropriate, render judgment thereon, or remand the matter to any administrative or executive body or official with such direction as it may deem proper and just."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1295?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1295. Jurisdiction of the United States Court of Appeals for the Federal Circuit","tname":"Judiciary and Judicial Procedure","by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(c)"],"by":{"0":"40"}},{"t":"usc","label":"28 U.S.C. § 1920","url":"https://www.law.cornell.edu/uscode/text/28/1920","by":{"0":"20","1":"41, 42"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(g)(1)"],"by":{"0":"36","1":"37"}},{"t":"usc","label":"29 U.S.C. § 1370","url":"https://www.law.cornell.edu/uscode/text/29/1370","subs":["(e)(1)"],"stext":{"head":"§1370. Enforcement authority relating to terminations of single-employer plans","paras":[[0,"(a) In general"],[0,"Any person who is with respect to a single-employer plan a fiduciary, contributing sponsor, member of a contributing sponsor's controlled group, participant, or beneficiary, and is adversely affected by an act or practice of any party (other than the corporation) in violation of any provision of section 1341, 1342, 1362, 1363, 1364, or 1369 of this title, or who is an employee organization representing such a participant or beneficiary so adversely affected for purposes of collective bargaining with respect to such plan, may bring an action—"],[1,"(1) to enjoin such act or practice, or"],[1,"(2) to obtain other appropriate equitable relief (A) to redress such violation or (B) to enforce such provision."],[0,"(b) Status of plan as party to action and with respect to legal process"],[0,"A single-employer plan may be sued under this section as an entity. Service of summons, subpoena, or other legal process of a court upon a trustee or an administrator of a single-employer plan in such trustee's or administrator's capacity as such shall constitute service upon the plan. If a plan has not designated in the summary plan description of the plan an individual as agent for the service of legal process, service upon any contributing sponsor of the plan shall constitute such service. Any money judgment under this section against a single-employer plan shall be enforceable only against the plan as an entity and shall not be enforceable against any other person unless liability against such person is established in such person's individual capacity."],[0,"(c) Jurisdiction and venue"],[0,"The district courts of the United States shall have exclusive jurisdiction of civil actions under this section. Such actions may be brought in the district where the plan is administered, where the violation took place, or where a defendant resides or may be found, and process may be served in any other district where a defendant resides or may be found. The district courts of the United States shall have jurisdiction, without regard to the amount in controversy or the citizenship of the parties, to grant the relief provided for in subsection (a) in any action."],[0,"(d) Right of corporation to intervene"],[0,"A copy of the complaint or notice of appeal in any action under this section shall be served upon the corporation by certified mail. The corporation shall have the right in its discretion to intervene in any action."],[0,"(e) Awards of costs and expenses"],[0,"(1) General rule"],[1,"In any action brought under this section, the court in its discretion may award all or a portion of the costs and expenses incurred in connection with such action, including reasonable attorney's fees, to any party who prevails or substantially prevails in such action."],[0,"(2) Exemption for plans"],[1,"Notwithstanding the preceding provisions of this subsection, no plan shall be required in any action to pay any costs and expenses (including attorney's fees)."],[0,"(f) Limitation on actions"],[0,"(1) In general"],[1,"Except as provided in paragraph (3), an action under this section may not be brought after the later of—"],[2,"(A) 6 years after the date on which the cause of action arose, or"],[2,"(B) 3 years after the applicable date specified in paragraph (2)."],[0,"(2) Applicable date"],[0,"(A) General rule"],[2,"Except as provided in subparagraph (B), the applicable date specified in this paragraph is the earliest date on which the plaintiff acquired or should have acquired actual knowledge of the existence of such cause of action."],[0,"(B) Special rule for plaintiffs who are fiduciaries"],[2,"In the case of a plaintiff who is a fiduciary bringing the action in the exercise of fiduciary duties, the applicable date specified in this paragraph is the date on which the plaintiff became a fiduciary with respect to the plan if such date is later than the date described in subparagraph (A)."],[0,"(3) Cases of fraud or concealment"],[1,"In the case of fraud or concealment, the period described in paragraph (1)(B) shall be extended to 6 years after the applicable date specified in paragraph (2)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1370?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1370. Enforcement authority relating to terminations of single-employer plans","tname":"Labor","by":{"0":"40"}},{"t":"usc","label":"29 U.S.C. § 1451","url":"https://www.law.cornell.edu/uscode/text/29/1451","subs":["(e)"],"by":{"0":"40"}},{"t":"usc","label":"30 U.S.C. § 815","url":"https://www.law.cornell.edu/uscode/text/30/815","subs":["(c)(3)"],"by":{"0":"40"}},{"t":"usc","label":"30 U.S.C. § 938","url":"https://www.law.cornell.edu/uscode/text/30/938","subs":["(c)"],"by":{"0":"40"}},{"t":"usc","label":"33 U.S.C. § 928","url":"https://www.law.cornell.edu/uscode/text/33/928","subs":["(a)"],"by":{"0":"34"}},{"t":"usc","label":"33 U.S.C. § 1365","url":"https://www.law.cornell.edu/uscode/text/33/1365","subs":["(d)"],"by":{"0":"34"}},{"t":"usc","label":"33 U.S.C. § 1367","url":"https://www.law.cornell.edu/uscode/text/33/1367","subs":["(c)"],"by":{"0":"40"}},{"t":"usc","label":"35 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/35/2","subs":["(a)(1)"],"by":{"0":"3"}},{"t":"usc","label":"35 U.S.C. § 6","url":"https://www.law.cornell.edu/uscode/text/35/6","subs":["(b)(1)"],"by":{"0":"3"}},{"t":"usc","label":"35 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/35/41","subs":["(a)(2)(c)"],"by":{"0":"35"}},{"t":"usc","label":"35 U.S.C. § 63","url":"https://www.law.cornell.edu/uscode/text/35/63","subs":["(1934)"],"by":{"0":"9"}},{"t":"usc","label":"35 U.S.C. § 103","url":"https://www.law.cornell.edu/uscode/text/35/103","by":{"0":"9"}},{"t":"usc","label":"35 U.S.C. § 131","url":"https://www.law.cornell.edu/uscode/text/35/131","by":{"0":"3"}},{"t":"usc","label":"35 U.S.C. § 134","url":"https://www.law.cornell.edu/uscode/text/35/134","by":{"0":"3"}},{"t":"usc","label":"35 U.S.C. § 141","url":"https://www.law.cornell.edu/uscode/text/35/141","subs":["(a)"],"stext":{"head":"§141. Appeal to Court of Appeals for the Federal Circuit","paras":[[0,"(a) Examinations.—An applicant who is dissatisfied with the final decision in an appeal to the Patent Trial and Appeal Board under section 134(a) may appeal the Board's decision to the United States Court of Appeals for the Federal Circuit. By filing such an appeal, the applicant waives his or her right to proceed under section 145."],[0,"(b) Reexaminations.—A patent owner who is dissatisfied with the final decision in an appeal of a reexamination to the Patent Trial and Appeal Board under section 134(b) may appeal the Board's decision only to the United States Court of Appeals for the Federal Circuit."],[0,"(c) Post-Grant and Inter Partes Reviews.—A party to an inter partes review or a post-grant review who is dissatisfied with the final written decision of the Patent Trial and Appeal Board under section 318(a) or 328(a) (as the case may be) may appeal the Board's decision only to the United States Court of Appeals for the Federal Circuit."],[0,"(d) Derivation Proceedings.—A party to a derivation proceeding who is dissatisfied with the final decision of the Patent Trial and Appeal Board in the proceeding may appeal the decision to the United States Court of Appeals for the Federal Circuit, but such appeal shall be dismissed if any adverse party to such derivation proceeding, within 20 days after the appellant has filed notice of appeal in accordance with section 142, files notice with the Director that the party elects to have all further proceedings conducted as provided in section 146. If the appellant does not, within 30 days after the filing of such notice by the adverse party, file a civil action under section 146, the Board's decision shall govern the further proceedings in the case."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/141?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":3,"head":"§141. Appeal to Court of Appeals for the Federal Circuit","tname":"Patents","by":{"0":"42, 42","1":"2, 51","2":"8, 9, 22, 8"}},{"t":"usc","label":"35 U.S.C. § 144","url":"https://www.law.cornell.edu/uscode/text/35/144","stext":{"head":"§144. Decision on appeal","paras":[[0,"The United States Court of Appeals for the Federal Circuit shall review the decision from which an appeal is taken on the record before the Patent and Trademark Office. Upon its determination the court shall issue to the Director its mandate and opinion, which shall be entered of record in the Patent and Trademark Office and shall govern the further proceedings in the case."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/144?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§144. Decision on appeal","tname":"Patents","by":{"0":"42"}},{"t":"usc","label":"35 U.S.C. § 145","url":"https://www.law.cornell.edu/uscode/text/35/145","stext":{"head":"§145. Civil action to obtain patent","paras":[[0,"An applicant dissatisfied with the decision of the Patent Trial and Appeal Board in an appeal under section 134(a) may, unless appeal has been taken to the United States Court of Appeals for the Federal Circuit, have remedy by civil action against the Director in the United States District Court for the Eastern District of Virginia if commenced within such time after such decision, not less than sixty days, as the Director appoints. The court may adjudge that such applicant is entitled to receive a patent for his invention, as specified in any of his claims involved in the decision of the Patent Trial and Appeal Board, as the facts in the case may appear and such adjudication shall authorize the Director to issue such patent on compliance with the requirements of law. All the expenses of the proceedings shall be paid by the applicant."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/145?type=usc&year=mostrecent&link-type=html"},"op":34,"ar":10,"head":"§145. Civil action to obtain patent","tname":"Patents","by":{"0":"42","1":"passim","2":"passim"}},{"t":"usc","label":"35 U.S.C. § 285","url":"https://www.law.cornell.edu/uscode/text/35/285","stext":{"head":"§285. Attorney fees","paras":[[0,"The court in exceptional cases may award reasonable attorney fees to the prevailing party."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/285?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§285. Attorney fees","tname":"Patents","by":{"0":"42","1":"3, 26"}},{"t":"usc","label":"35 U.S.C. § 297","url":"https://www.law.cornell.edu/uscode/text/35/297","subs":["(b)(1)"],"stext":{"head":"§297. Improper and deceptive invention promotion","paras":[[0,"(a) In General.—An invention promoter shall have a duty to disclose the following information to a customer in writing, prior to entering into a contract for invention promotion services:"],[1,"(1) the total number of inventions evaluated by the invention promoter for commercial potential in the past 5 years, as well as the number of those inventions that received positive evaluations, and the number of those inventions that received negative evaluations;"],[1,"(2) the total number of customers who have contracted with the invention promoter in the past 5 years, not including customers who have purchased trade show services, research, advertising, or other nonmarketing services from the invention promoter, or who have defaulted in their payment to the invention promoter;"],[1,"(3) the total number of customers known by the invention promoter to have received a net financial profit as a direct result of the invention promotion services provided by such invention promoter;"],[1,"(4) the total number of customers known by the invention promoter to have received license agreements for their inventions as a direct result of the invention promotion services provided by such invention promoter; and"],[1,"(5) the names and addresses of all previous invention promotion companies with which the invention promoter or its officers have collectively or individually been affiliated in the previous 10 years."],[0,"(b) Civil Action.—(1) Any customer who enters into a contract with an invention promoter and who is found by a court to have been injured by any material false or fraudulent statement or representation, or any omission of material fact, by that invention promoter (or any agent, employee, director, officer, partner, or independent contractor of such invention promoter), or by the failure of that invention promoter to disclose such information as required under subsection (a), may recover in a civil action against the invention promoter (or the officers, directors, or partners of such invention promoter), in addition to reasonable costs and attorneys' fees—"],[1,"(A) the amount of actual damages incurred by the customer; or"],[1,"(B) at the election of the customer at any time before final judgment is rendered, statutory damages in a sum of not more than $5,000, as the court considers just."],[0,"(2) Notwithstanding paragraph (1), in a case where the customer sustains the burden of proof, and the court finds, that the invention promoter intentionally misrepresented or omitted a material fact to such customer, or willfully failed to disclose such information as required under subsection (a), with the purpose of deceiving that customer, the court may increase damages to not more than three times the amount awarded, taking into account past complaints made against the invention promoter that resulted in regulatory sanctions or other corrective actions based on those records compiled by the Commissioner of Patents under subsection (d)."],[0,"(c) Definitions.—For purposes of this section—"],[1,"(1) a \"contract for invention promotion services\" means a contract by which an invention promoter undertakes invention promotion services for a customer;"],[1,"(2) a \"customer\" is any individual who enters into a contract with an invention promoter for invention promotion services;"],[1,"(3) the term \"invention promoter\" means any person, firm, partnership, corporation, or other entity who offers to perform or performs invention promotion services for, or on behalf of, a customer, and who holds itself out through advertising in any mass media as providing such services, but does not include—"],[2,"(A) any department or agency of the Federal Government or of a State or local government;"],[2,"(B) any nonprofit, charitable, scientific, or educational organization, qualified under applicable State law or described under section 170(b)(1)(A) of the Internal Revenue Code of 1986;"],[2,"(C) any person or entity involved in the evaluation to determine commercial potential of, or offering to license or sell, a utility patent or a previously filed nonprovisional utility patent application;"],[2,"(D) any party participating in a transaction involving the sale of the stock or assets of a business; or"],[2,"(E) any party who directly engages in the business of retail sales of products or the distribution of products; and"],[1,"(4) the term \"invention promotion services\" means the procurement or attempted procurement for a customer of a firm, corporation, or other entity to develop and market products or services that include the invention of the customer."],[0,"(d) Records of Complaints.—"],[1,"(1) Release of complaints.—The Commissioner of Patents shall make all complaints received by the Patent and Trademark Office involving invention promoters publicly available, together with any response of the invention promoters. The Commissioner of Patents shall notify the invention promoter of a complaint and provide a reasonable opportunity to reply prior to making such complaint publicly available."],[1,"(2) Request for complaints.—The Commissioner of Patents may request complaints relating to invention promotion services from any Federal or State agency and include such complaints in the records maintained under paragraph (1), together with any response of the invention promoters."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/297?type=usc&year=mostrecent&link-type=html"},"head":"§297. Improper and deceptive invention promotion","tname":"Patents","by":{"0":"42","1":"3, 26"}},{"t":"usc","label":"42 U.S.C. § 247d-6d","url":"https://www.law.cornell.edu/uscode/text/42/247d-6d","subs":["(e)(9)"],"by":{"0":"40"}},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","subs":["(1988)","(b)"],"by":{"0":"40, 34","2":"21"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(g)(2)(B)"],"by":{"0":"34"}},{"t":"usc","label":"42 U.S.C. § 3612","url":"https://www.law.cornell.edu/uscode/text/42/3612","subs":["(p)"],"by":{"0":"34"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","by":{"0":"36"}},{"t":"usc","label":"45 U.S.C. § 153","url":"https://www.law.cornell.edu/uscode/text/45/153","subs":["(p)"],"by":{"0":"34"}},{"t":"usc","label":"52 U.S.C. § 10310","url":"https://www.law.cornell.edu/uscode/text/52/10310","subs":["(e)"],"by":{"0":"34, 41"}},{"t":"reg","label":"82 Fed. Reg. 52,780","url":"https://www.govinfo.gov/link/fr/82/52780","by":{"0":"27"}},{"t":"case","label":"Air Turbine Tech., Inc. v. Quarles & Brady, LLC","cite":"165 So. 3d 816","y":2015,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%203d/165/816/","by":{"1":"21-22"}},{"t":"case","label":"Anderson v. Farns","cite":"7 Blackf. 343","y":1845,"court":"Ind.","url":"https://www.courtlistener.com/c/Blackf./7/343/","by":{"1":"16"}},{"t":"case","label":"Arcambel v. Wiseman","cite":"3 U.S. 306","y":1796,"id":"scdb/1796-013","sc":1,"op":1,"sum":"THE decree of the Circuit Court, for the Diftritft of Rhode Ifland, was affirmed-in this caufe, without argument, the principal queftion, which it involved, having been juft decided upon the difcuffion of another writ of error. It appeared, however, by an eftimate of the damages on which the decree was founded, and which was annexed to the record, that a charge of 1600 dollars for counfel’s fees in the courts below, …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Ark. Dep’t of Human Servs., Div. of Econ. & Med. Servs. v. Kistler","cite":"320 Ark. 501","y":1995,"url":"https://www.courtlistener.com/c/Ark./320/501/","by":{"1":"21"}},{"t":"case","label":"Ball v. Vason","cite":"56 Ga. 264","y":1876,"url":"https://www.courtlistener.com/c/Ga./56/264/","sum":"Holding that order awarding “costs and expenses” did not encompass counsel fees.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"Bebchick v. Pub. Util. Comm’n","cite":"318 F.2d 187","y":1963,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/318/187/","by":{"1":"42","2":"21"}},{"t":"case","label":"Bishop v. Day","cite":"13 Vt. 81","y":1841,"url":"https://www.courtlistener.com/c/Vt./13/81/","by":{"1":"16"}},{"t":"case","label":"Booking.com B.V. v. United States","cite":"915 F.3d 171","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/915/171/","by":{"1":"33"}},{"t":"case","label":"Buckhannon Bd. & Care Home, Inc. v. West Virginia Dept. of Health and Human Resources","cite":"532 U.S. 598","y":2001,"id":"2000/99-1848","sc":1,"sum":"The Court held that the \"catalyst theory\" is not a permissible basis for the award of attorney's fees under the FHAA and ADA. \"In the United States, parties are ordinarily required to bear their own attorney's fees -- the prevailing party is not entitled to collect from the loser,\" wrote Chief Justice Rehnquist, \"[u]nder this 'American Rule,' we follow 'a general practice of not awarding fees to a prevailing party absent explicit statutory authority.'\" Dissenting, Justice Ruth Bader Ginsburg argued that \"Congress prescribed fee-shifting provisions like those included in the FHAA and ADA to encourage private enforcement of laws designed to advance civil rights.","sumSrc":"Oyez","by":{"1":"8, 49"}},{"t":"case","label":"Clay v. United States","cite":"537 U.S. 522","y":2003,"id":"2002/01-1500","sc":1,"sum":"The Court held that, for the purpose of starting the clock on section 2255's one-year limitation period, a judgment of conviction becomes final when the time expires for filing a petition for certiorari contesting the appellate court's affirmation of the conviction. Under this rule, Clay's section 2255 motion was timely filed.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"Conroy v. Aniskoff","cite":"507 U.S. 511","y":1993,"id":"1992/91-1353","sc":1,"sum":"When petitioner Conroy, an officer in the United States Army, failed to pay local real estate taxes on property he owned in Danforth, Maine, the town acquired the property and sold it. In his suit against the town and the property's purchasers, Conroy claimed that § 525 of the Soldiers' and Sailors' Civil Relief Act of 1940-which provides that the \"period of military service\" shall not \"be included in computing any …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Cracker Barrel Old Country Store, Inc. v. Epperson","cite":"284 S.W.3d 303","y":2009,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W.3d/284/303/","by":{"1":"21"}},{"t":"case","label":"F. D. Rich Co. v. United States","cite":"417 U.S. 116","y":1974,"id":"1973/72-1382","sc":1,"sum":"Petitioner F. D. Rich Co., the prime contractor on a federal housing project in California, had two separate contracts for the project with Cerpac Co., one contract being for Cerpac to select, modify, detail, and install all custom millwork and the other being for Cerpac to supply all exterior plywood. Cerpac in turn ordered the lumber called for under the plywood contract from respondent. When Rich needed plywood …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30","2":"20"}},{"t":"case","label":"Fiorito v. Goerig","cite":"179 P.2d 316","y":1947,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/179/316/","by":{"1":"21"}},{"t":"case","label":"Fleischmann Distilling Corp. v. Maier Brewing Co.","cite":"386 U.S. 714","y":1967,"id":"1966/214","sc":1,"sum":"Attorney's fees are not recoverable under the Lanham Act. The meticulous statutory provisions set forth in § 35 are exclusive of any other monetary remedies for violation of rights protected by the Act. Pp. 717-721. 359 F. 2d 156, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12, 30, 34","2":"20"}},{"t":"case","label":"Flora v. United States","cite":"362 U.S. 145","y":1960,"id":"1959/492","sc":1,"sum":"Under 28 U. S. C. § 1346 (a)(1), a Federal District Court does not have jurisdiction of an action by a taxpayer for refund of a part payment made by him on an assessment for an alleged deficiency in his income tax. The taxpayer must pay the full amount of the assessment before he may challenge its validity in an action under § 1346 (a) (1). Flora v. United States, 357 U. S. 63, reaffirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Fogerty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"sum":"The Court held that while attorney's fees are awarded from time to time to prevailing defendants or plaintiffs, this practice is entirely subject to the deciding court's discretion. Indeed, the Court observed, that the statute in question emphasizes such discretion by stating in relevant part that a court \"may\" award attorney's fees.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Hayden v. Sample","cite":"10 Mo. 215","y":1846,"url":"https://www.courtlistener.com/c/Mo./10/215/","sum":"Noting defendant’s request that jury be instructed to ignore evidence of “the expenses incurred . . . and the fees paid counsel and attornies”.","sumSrc":"brief:1","by":{"1":"16"}},{"t":"case","label":"Hensley v. Eckerhart","cite":"461 U.S. 424","y":1983,"id":"1982/81-1244","sc":1,"sum":"The District Court did not properly consider the relationship between the extent of success and the amount of the attorney's fee award. The extent of a plaintiff's success is a crucial factor in determining the proper amount of an attorney's fee award under § 1988. Where the plaintiff failed to prevail on a claim unrelated to the successful claims, the hours spent on the unsuccessful claim should be excluded in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Hickman v. Quinn","cite":"14 Tenn. 96","y":1834,"url":"https://www.courtlistener.com/c/Tenn./14/96/","sum":"Explaining that defendants deducted “their expenses, attorney’s fees, etc.” from amount voluntarily given to plaintiff.","sumSrc":"brief:1","by":{"1":"16"}},{"t":"case","label":"Highmark Inc. v. Allcare Health Mgmt. Sys., Inc.","cite":"572 U.S. 559","y":2014,"id":"2013/12-1163","sc":1,"sum":"The Court held that a district court is the best place to determine whether or not a lawsuit is objectively baseless.","sumSrc":"Oyez","by":{"1":"16","2":"6"}},{"t":"case","label":"Lopez v. Davis","cite":"531 U.S. 230","y":2001,"id":"2000/99-7504","sc":1,"sum":"The Court held that the categorically denial of early release to a prisoner who committed felony using firearm is a permissible exercise of the BOP's discretion, even if the prisoner has successfully completed a substance abuse program. \"The Bureau reasonably concluded that an inmate's prior involvement with firearms, in connection with the commission of a felony, suggests his readiness to resort to life-endangering violence and therefore appropriately determines the early release decision,\" wrote Justice Ginsburg for the majority.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Massachusetts v. Westcott","cite":"431 U.S. 322","y":1977,"id":"1976/75-1775","sc":1,"sum":"Where it appears that there may be a statutory basis for providing relief to respondent owner of a federally enrolled and licensed fishing vessel against enforcement of a Massachusetts statute prohibiting nonresidents from dragging for fish by beam or otter trawl in Vineyard Sound during certain months, Douglas v Seacoast Products, Inc., ante, p. 265, this Court will not decide the question presented as to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"McAdam v. Dean Witter Reynolds, Inc.","cite":"896 F.2d 750","y":1990,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/896/750/","by":{"1":"22"}},{"t":"case","label":"McQuade v. Richland Water Co.","cite":"1912 WL 3724","y":1912,"court":"Pa. Com. Pl.","by":{"1":"21"}},{"t":"case","label":"Missouri v. Jenkins by Agyei","cite":"491 U.S. 274","y":1989,"id":"1988/88-64","sc":1,"sum":"No and Yes. Justice William J. Brennan Jr. delivered the opinion for a 7-1 court. The Court referred to its decision in Hutto v. Finney to establish that the Eleventh Amendment does not apply \"to an award of attorney's fees against a State.\" Therefore \"it follows that the same is true for the calculation of the amount of the fee.\" Charging current rates for lawyers compensated for the delay in payment to them.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Morris v. Way","cite":"16 Ohio 469","y":1847,"url":"https://www.courtlistener.com/c/Ohio/16/469/","by":{"1":"16"}},{"t":"case","label":"Nightingale Home Healthcare, Inc. v. Anodyne Therapy, LLC","cite":"626 F.3d 958","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/626/958/","by":{"1":"27"}},{"t":"case","label":"Ragan v. Ragan","cite":"119 S.E. 882","y":1923,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E./119/882/","op":1,"by":{"1":"21"}},{"t":"case","label":"Royal Disc. Corp. v. Luxor Motor Sales Corp.","cite":"170 N.Y.S.2d 382","y":1957,"court":"App. Term","url":"https://www.courtlistener.com/c/N.Y.S.2d/170/382/","by":{"1":"21"}},{"t":"case","label":"Runyon v. McCrary","cite":"427 U.S. 160","y":1976,"id":"1975/75-62","sc":1,"sum":"The Court held that Section 1981 prohibited the racially discriminatory policies of the schools.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Sandvik Aktiebolag v. Samuels","cite":"1991 WL 25774","y":1991,"court":"D.D.C. Feb. 7","by":{"1":"2, 41"}},{"t":"case","label":"Shammas v. Focarino","cite":"990 F. Supp. 2d 587","y":2014,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/990/587/","by":{"1":"4"}},{"t":"case","label":"State v. Williams","cite":"13 Ohio 495","y":1844,"url":"https://www.courtlistener.com/c/Ohio/13/495/","by":{"1":"16"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. U.S. ex rel. Rigsby","cite":"137 S. Ct. 436","y":2016,"id":"2016/15-513","sc":1,"sum":"The Court determined that a violation of the False Claims Act’s seal requirement does not mandate dismissal of the complaint.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Summit Valley Indus. Inc. v. Local 112 United Bhd of Carpenters","cite":"456 U.S. 717","y":1982,"id":"1981/81-497","sc":1,"op":1,"sum":"Observing that the American Rule “has been consistently followed for almost 200 years”.","sumSrc":"opinion","by":{"1":"7, 30","2":"20"}},{"t":"case","label":"Swartzel v. Rogers","cite":"3 Kan. 380","y":1866,"url":"https://www.courtlistener.com/c/Kan./3/380/","by":{"1":"20"}},{"t":"case","label":"Thomas v. Jones","cite":"84 Ala. 302","y":1888,"url":"https://www.courtlistener.com/c/Ala./84/302/","sum":"Holding that order awarding “costs and expenses” did not encompass counsel fees.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"VSI Enters., Inc. v. Edwards","cite":"238 Ga. App. 369","url":"https://www.courtlistener.com/c/Ga.%20App./238/369/","by":{"1":"21"}},{"t":"usc","label":"11 U.S.C. § 327","url":"https://www.law.cornell.edu/uscode/text/11/327","subs":["(a)"],"by":{"1":"43"}},{"t":"usc","label":"11 U.S.C. § 363","url":"https://www.law.cornell.edu/uscode/text/11/363","subs":["(n)"],"stext":{"head":"§363. Use, sale, or lease of property","paras":[[0,"(a) In this section, \"cash collateral\" means cash, negotiable instruments, documents of title, securities, deposit accounts, or other cash equivalents whenever acquired in which the estate and an entity other than the estate have an interest and includes the proceeds, products, offspring, rents, or profits of property and the fees, charges, accounts or other payments for the use or occupancy of rooms and other public facilities in hotels, motels, or other lodging properties subject to a security interest as provided in section 552(b) of this title, whether existing before or after the commencement of a case under this title."],[0,"(b)(1) The trustee, after notice and a hearing, may use, sell, or lease, other than in the ordinary course of business, property of the estate, except that if the debtor in connection with offering a product or a service discloses to an individual a policy prohibiting the transfer of personally identifiable information about individuals to persons that are not affiliated with the debtor and if such policy is in effect on the date of the commencement of the case, then the trustee may not sell or lease personally identifiable information to any person unless—"],[1,"(A) such sale or such lease is consistent with such policy; or"],[1,"(B) after appointment of a consumer privacy ombudsman in accordance with section 332, and after notice and a hearing, the court approves such sale or such lease—"],[2,"(i) giving due consideration to the facts, circumstances, and conditions of such sale or such lease; and"],[2,"(ii) finding that no showing was made that such sale or such lease would violate applicable nonbankruptcy law."],[0,"(2) If notification is required under subsection (a) of section 7A of the Clayton Act in the case of a transaction under this subsection, then—"],[1,"(A) notwithstanding subsection (a) of such section, the notification required by such subsection to be given by the debtor shall be given by the trustee; and"],[1,"(B) notwithstanding subsection (b) of such section, the required waiting period shall end on the 15th day after the date of the receipt, by the Federal Trade Commission and the Assistant Attorney General in charge of the Antitrust Division of the Department of Justice, of the notification required under such subsection (a), unless such waiting period is extended—"],[2,"(i) pursuant to subsection (e)(2) of such section, in the same manner as such subsection (e)(2) applies to a cash tender offer;"],[2,"(ii) pursuant to subsection (g)(2) of such section; or"],[2,"(iii) by the court after notice and a hearing."],[0,"(c)(1) If the business of the debtor is authorized to be operated under section 721, 1108, 1183, 1184, 1203, 1204, or 1304 of this title and unless the court orders otherwise, the trustee may enter into transactions, including the sale or lease of property of the estate, in the ordinary course of business, without notice or a hearing, and may use property of the estate in the ordinary course of business without notice or a hearing."],[0,"(2) The trustee may not use, sell, or lease cash collateral under paragraph (1) of this subsection unless—"],[1,"(A) each entity that has an interest in such cash collateral consents; or"],[1,"(B) the court, after notice and a hearing, authorizes such use, sale, or lease in accordance with the provisions of this section."],[0,"(3) Any hearing under paragraph (2)(B) of this subsection may be a preliminary hearing or may be consolidated with a hearing under subsection (e) of this section, but shall be scheduled in accordance with the needs of the debtor. If the hearing under paragraph (2)(B) of this subsection is a preliminary hearing, the court may authorize such use, sale, or lease only if there is a reasonable likelihood that the trustee will prevail at the final hearing under subsection (e) of this section. The court shall act promptly on any request for authorization under paragraph (2)(B) of this subsection."],[0,"(4) Except as provided in paragraph (2) of this subsection, the trustee shall segregate and account for any cash collateral in the trustee's possession, custody, or control."],[0,"(d) The trustee may use, sell, or lease property under subsection (b) or (c) of this section—"],[1,"(1) in the case of a debtor that is a corporation or trust that is not a moneyed business, commercial corporation, or trust, only in accordance with nonbankruptcy law applicable to the transfer of property by a debtor that is such a corporation or trust; and"],[1,"(2) only to the extent not inconsistent with any relief granted under subsection (c), (d), (e), or (f) of section 362."],[0,"(e) Notwithstanding any other provision of this section, at any time, on request of an entity that has an interest in property used, sold, or leased, or proposed to be used, sold, or leased, by the trustee, the court, with or without a hearing, shall prohibit or condition such use, sale, or lease as is necessary to provide adequate protection of such interest. This subsection also applies to property that is subject to any unexpired lease of personal property (to the exclusion of such property being subject to an order to grant relief from the stay under section 362)."],[0,"(f) The trustee may sell property under subsection (b) or (c) of this section free and clear of any interest in such property of an entity other than the estate, only if—"],[1,"(1) applicable nonbankruptcy law permits sale of such property free and clear of such interest;"],[1,"(2) such entity consents;"],[1,"(3) such interest is a lien and the price at which such property is to be sold is greater than the aggregate value of all liens on such property;"],[1,"(4) such interest is in bona fide dispute; or"],[1,"(5) such entity could be compelled, in a legal or equitable proceeding, to accept a money satisfaction of such interest."],[0,"(g) Notwithstanding subsection (f) of this section, the trustee may sell property under subsection (b) or (c) of this section free and clear of any vested or contingent right in the nature of dower or curtesy."],[0,"(h) Notwithstanding subsection (f) of this section, the trustee may sell both the estate's interest, under subsection (b) or (c) of this section, and the interest of any co-owner in property in which the debtor had, at the time of the commencement of the case, an undivided interest as a tenant in common, joint tenant, or tenant by the entirety, only if—"],[1,"(1) partition in kind of such property among the estate and such co-owners is impracticable;"],[1,"(2) sale of the estate's undivided interest in such property would realize significantly less for the estate than sale of such property free of the interests of such co-owners;"],[1,"(3) the benefit to the estate of a sale of such property free of the interests of co-owners outweighs the detriment, if any, to such co-owners; and"],[1,"(4) such property is not used in the production, transmission, or distribution, for sale, of electric energy or of natural or synthetic gas for heat, light, or power."],[0,"(i) Before the consummation of a sale of property to which subsection (g) or (h) of this section applies, or of property of the estate that was community property of the debtor and the debtor's spouse immediately before the commencement of the case, the debtor's spouse, or a co-owner of such property, as the case may be, may purchase such property at the price at which such sale is to be consummated."],[0,"(j) After a sale of property to which subsection (g) or (h) of this section applies, the trustee shall distribute to the debtor's spouse or the co-owners of such property, as the case may be, and to the estate, the proceeds of such sale, less the costs and expenses, not including any compensation of the trustee, of such sale, according to the interests of such spouse or co-owners, and of the estate."],[0,"(k) At a sale under subsection (b) of this section of property that is subject to a lien that secures an allowed claim, unless the court for cause orders otherwise the holder of such claim may bid at such sale, and, if the holder of such claim purchases such property, such holder may offset such claim against the purchase price of such property."],[0,"(l) Subject to the provisions of section 365, the trustee may use, sell, or lease property under subsection (b) or (c) of this section, or a plan under chapter 11, 12, or 13 of this title may provide for the use, sale, or lease of property, notwithstanding any provision in a contract, a lease, or applicable law that is conditioned on the insolvency or financial condition of the debtor, on the commencement of a case under this title concerning the debtor, or on the appointment of or the taking possession by a trustee in a case under this title or a custodian, and that effects, or gives an option to effect, a forfeiture, modification, or termination of the debtor's interest in such property."],[0,"(m) The reversal or modification on appeal of an authorization under subsection (b) or (c) of this section of a sale or lease of property does not affect the validity of a sale or lease under such authorization to an entity that purchased or leased such property in good faith, whether or not such entity knew of the pendency of the appeal, unless such authorization and such sale or lease were stayed pending appeal."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/363?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§363. Use, sale, or lease of property","tname":"Bankruptcy","by":{"1":"17"}},{"t":"usc","label":"12 U.S.C. § 1464","url":"https://www.law.cornell.edu/uscode/text/12/1464","subs":["(d)(1)(B)(vii)"],"by":{"1":"17"}},{"t":"usc","label":"12 U.S.C. § 5009","url":"https://www.law.cornell.edu/uscode/text/12/5009","subs":["(a)(1)(B)"],"by":{"1":"18"}},{"t":"usc","label":"15 U.S.C. § 1117","url":"https://www.law.cornell.edu/uscode/text/15/1117","subs":["(a)","(b)","(1964)"],"by":{"1":"27, 27, 4","2":"20"}},{"t":"usc","label":"15 U.S.C. § 1122","url":"https://www.law.cornell.edu/uscode/text/15/1122","subs":["(c)"],"by":{"1":"4"}},{"t":"usc","label":"15 U.S.C. § 6309","url":"https://www.law.cornell.edu/uscode/text/15/6309","subs":["(d)"],"by":{"1":"18"}},{"t":"usc","label":"18 U.S.C. § 2707","url":"https://www.law.cornell.edu/uscode/text/18/2707","subs":["(b)(3)"],"by":{"1":"14"}},{"t":"usc","label":"26 U.S.C. § 6673","url":"https://www.law.cornell.edu/uscode/text/26/6673","subs":["(a)(2)(A)"],"stext":{"head":"§6673. Sanctions and costs awarded by courts","paras":[[0,"(a) Tax court proceedings"],[0,"(1) Procedures instituted primarily for delay, etc."],[1,"Whenever it appears to the Tax Court that—"],[2,"(A) proceedings before it have been instituted or maintained by the taxpayer primarily for delay,"],[2,"(B) the taxpayer's position in such proceeding is frivolous or groundless, or"],[2,"(C) the taxpayer unreasonably failed to pursue available administrative remedies,"],[1,"the Tax Court, in its decision, may require the taxpayer to pay to the United States a penalty not in excess of $25,000."],[0,"(2) Counsel's liability for excessive costs"],[1,"Whenever it appears to the Tax Court that any attorney or other person admitted to practice before the Tax Court has multiplied the proceedings in any case unreasonably and vexatiously, the Tax Court may require—"],[2,"(A) that such attorney or other person pay personally the excess costs, expenses, and attorneys' fees reasonably incurred because of such conduct, or"],[2,"(B) if such attorney is appearing on behalf of the Commissioner of Internal Revenue, that the United States pay such excess costs, expenses, and attorneys' fees in the same manner as such an award by a district court."],[0,"(b) Proceedings in other courts"],[0,"(1) Claims under section 7433"],[1,"Whenever it appears to the court that the taxpayer's position in the proceedings before the court instituted or maintained by such taxpayer under section 7433 is frivolous or groundless, the court may require the taxpayer to pay to the United States a penalty not in excess of $10,000."],[0,"(2) Collection of sanctions and costs"],[1,"In any civil proceeding before any court (other than the Tax Court) which is brought by or against the United States in connection with the determination, collection, or refund of any tax, interest, or penalty under this title, any monetary sanctions, penalties, or costs awarded by the court to the United States may be assessed by the Secretary and, upon notice and demand, may be collected in the same manner as a tax."],[0,"(3) Sanctions and costs awarded by a court of appeals"],[1,"In connection with any appeal from a proceeding in the Tax Court or a civil proceeding described in paragraph (2), an order of a United States Court of Appeals or the Supreme Court awarding monetary sanctions, penalties or court costs to the United States may be registered in a district court upon filing a certified copy of such order and shall be enforceable as other district court judgments. Any such sanctions, penalties, or costs may be assessed by the Secretary and, upon notice and demand, may be collected in the same manner as a tax."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6673?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6673. Sanctions and costs awarded by courts","tname":"Internal Revenue Code","by":{"1":"17"}},{"t":"usc","label":"28 U.S.C. § 1821","url":"https://www.law.cornell.edu/uscode/text/28/1821","by":{"1":"41, 42"}},{"t":"usc","label":"28 U.S.C. § 1875","url":"https://www.law.cornell.edu/uscode/text/28/1875","subs":["(d)(2)"],"by":{"1":"18"}},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","subs":["(b)","(d)(2)(A)"],"by":{"1":"18, 18"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(d)(1)"],"stext":{"head":"§3730. Civil actions for false claims","paras":[[0,"(a) Responsibilities of the Attorney General.—The Attorney General diligently shall investigate a violation under section 3729. If the Attorney General finds that a person has violated or is violating section 3729, the Attorney General may bring a civil action under this section against the person."],[0,"(b) Actions by Private Persons.—(1) A person may bring a civil action for a violation of section 3729 for the person and for the United States Government. The action shall be brought in the name of the Government. The action may be dismissed only if the court and the Attorney General give written consent to the dismissal and their reasons for consenting."],[0,"(2) A copy of the complaint and written disclosure of substantially all material evidence and information the person possesses shall be served on the Government pursuant to Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. The complaint shall be filed in camera, shall remain under seal for at least 60 days, and shall not be served on the defendant until the court so orders. The Government may elect to intervene and proceed with the action within 60 days after it receives both the complaint and the material evidence and information."],[0,"(3) The Government may, for good cause shown, move the court for extensions of the time during which the complaint remains under seal under paragraph (2). Any such motions may be supported by affidavits or other submissions in camera. The defendant shall not be required to respond to any complaint filed under this section until 20 days after the complaint is unsealed and served upon the defendant pursuant to Rule 4 of the Federal Rules of Civil Procedure."],[0,"(4) Before the expiration of the 60-day period or any extensions obtained under paragraph (3), the Government shall—"],[1,"(A) proceed with the action, in which case the action shall be conducted by the Government; or"],[1,"(B) notify the court that it declines to take over the action, in which case the person bringing the action shall have the right to conduct the action."],[0,"(5) When a person brings an action under this subsection, no person other than the Government may intervene or bring a related action based on the facts underlying the pending action."],[0,"(c) Rights of the Parties to Qui Tam Actions.—(1) If the Government proceeds with the action, it shall have the primary responsibility for prosecuting the action, and shall not be bound by an act of the person bringing the action. Such person shall have the right to continue as a party to the action, subject to the limitations set forth in paragraph (2)."],[0,"(2)(A) The Government may dismiss the action notwithstanding the objections of the person initiating the action if the person has been notified by the Government of the filing of the motion and the court has provided the person with an opportunity for a hearing on the motion."],[0,"(B) The Government may settle the action with the defendant notwithstanding the objections of the person initiating the action if the court determines, after a hearing, that the proposed settlement is fair, adequate, and reasonable under all the circumstances. Upon a showing of good cause, such hearing may be held in camera."],[0,"(C) Upon a showing by the Government that unrestricted participation during the course of the litigation by the person initiating the action would interfere with or unduly delay the Government's prosecution of the case, or would be repetitious, irrelevant, or for purposes of harassment, the court may, in its discretion, impose limitations on the person's participation, such as—"],[1,"(i) limiting the number of witnesses the person may call;"],[1,"(ii) limiting the length of the testimony of such witnesses;"],[1,"(iii) limiting the person's cross-examination of witnesses; or"],[1,"(iv) otherwise limiting the participation by the person in the litigation."],[0,"(D) Upon a showing by the defendant that unrestricted participation during the course of the litigation by the person initiating the action would be for purposes of harassment or would cause the defendant undue burden or unnecessary expense, the court may limit the participation by the person in the litigation."],[0,"(3) If the Government elects not to proceed with the action, the person who initiated the action shall have the right to conduct the action. If the Government so requests, it shall be served with copies of all pleadings filed in the action and shall be supplied with copies of all deposition transcripts (at the Government's expense). When a person proceeds with the action, the court, without limiting the status and rights of the person initiating the action, may nevertheless permit the Government to intervene at a later date upon a showing of good cause."],[0,"(4) Whether or not the Government proceeds with the action, upon a showing by the Government that certain actions of discovery by the person initiating the action would interfere with the Government's investigation or prosecution of a criminal or civil matter arising out of the same facts, the court may stay such discovery for a period of not more than 60 days. Such a showing shall be conducted in camera. The court may extend the 60-day period upon a further showing in camera that the Government has pursued the criminal or civil investigation or proceedings with reasonable diligence and any proposed discovery in the civil action will interfere with the ongoing criminal or civil investigation or proceedings."],[0,"(5) Notwithstanding subsection (b), the Government may elect to pursue its claim through any alternate remedy available to the Government, including any administrative proceeding to determine a civil money penalty. If any such alternate remedy is pursued in another proceeding, the person initiating the action shall have the same rights in such proceeding as such person would have had if the action had continued under this section. Any finding of fact or conclusion of law made in such other proceeding that has become final shall be conclusive on all parties to an action under this section. For purposes of the preceding sentence, a finding or conclusion is final if it has been finally determined on appeal to the appropriate court of the United States, if all time for filing such an appeal with respect to the finding or conclusion has expired, or if the finding or conclusion is not subject to judicial review."],[0,"(d) Award to Qui Tam Plaintiff.—(1) If the Government proceeds with an action brought by a person under subsection (b), such person shall, subject to the second sentence of this paragraph, receive at least 15 percent but not more than 25 percent of the proceeds of the action or settlement of the claim, depending upon the extent to which the person substantially contributed to the prosecution of the action. Where the action is one which the court finds to be based primarily on disclosures of specific information (other than information provided by the person bringing the action) relating to allegations or transactions in a criminal, civil, or administrative hearing, in a congressional, administrative, or Government 2 Accounting Office report, hearing, audit, or investigation, or from the news media, the court may award such sums as it considers appropriate, but in no case more than 10 percent of the proceeds, taking into account the significance of the information and the role of the person bringing the action in advancing the case to litigation. Any payment to a person under the first or second sentence of this paragraph shall be made from the proceeds. Any such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(2) If the Government does not proceed with an action under this section, the person bringing the action or settling the claim shall receive an amount which the court decides is reasonable for collecting the civil penalty and damages. The amount shall be not less than 25 percent and not more than 30 percent of the proceeds of the action or settlement and shall be paid out of such proceeds. Such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(3) Whether or not the Government proceeds with the action, if the court finds that the action was brought by a person who planned and initiated the violation of section 3729 upon which the action was brought, then the court may, to the extent the court considers appropriate, reduce the share of the proceeds of the action which the person would otherwise receive under paragraph (1) or (2) of this subsection, taking into account the role of that person in advancing the case to litigation and any relevant circumstances pertaining to the violation. If the person bringing the action is convicted of criminal conduct arising from his or her role in the violation of section 3729, that person shall be dismissed from the civil action and shall not receive any share of the proceeds of the action. Such dismissal shall not prejudice the right of the United States to continue the action, represented by the Department of Justice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3730?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3730. Civil actions for false claims","tname":"Money and Finance","by":{"1":"18"}},{"t":"usc","label":"33 U.S.C. § 1319","url":"https://www.law.cornell.edu/uscode/text/33/1319","subs":["(g)(9)"],"by":{"1":"14"}},{"t":"usc","label":"35 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/35/271","subs":["(e)(4)"],"by":{"1":"3, 26"}},{"t":"usc","label":"35 U.S.C. § 273","url":"https://www.law.cornell.edu/uscode/text/35/273","subs":["(f)"],"by":{"1":"3, 26"}},{"t":"usc","label":"35 U.S.C. § 296","url":"https://www.law.cornell.edu/uscode/text/35/296","subs":["(b)"],"by":{"1":"3, 26"}},{"t":"law","label":"Leahy-Smith America Invents Act, Pub. L. No. 112-29","url":"https://www.govinfo.gov/link/plaw/112/public/29","by":{"1":"3, 47","2":"14"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(d)"],"by":{"1":"45"}},{"t":"rule","label":"Fed. R. Evid. 201","url":"https://www.law.cornell.edu/rules/fre/rule_201","subs":["(b)"],"by":{"1":"47"}},{"t":"case","label":"Baldwin v. Reese","cite":"541 U.S. 27","y":2004,"id":"2003/02-964","sc":1,"sum":"The Court held that Reese did not \"fairly present\" his Sixth Amendment ineffective counsel claim to state courts. Federal law thus barred Reese from turning to federal courts. The state court could have understood Reese's claims were federal if the court had read the lower court opinion.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Commissioner v. Heininger","cite":"320 U.S. 467","y":1943,"id":"scdb/1943-017","sc":1,"sum":"1. Attorney's fees and other legal expenses, reasonable in amount, incurred by a taxpayer (a licensed dentist engaged in selling artificial dentures by mail) in resisting issuance by. the Postmaster General of a \"fraud order\" which would destroy his business, and in connection with subsequent proceedings on judicial review, the final result of which was unsuccessful for the taxpayer, held, in computing income tax …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Foreman v. Foreman","cite":"176 P.2d 144","y":1946,"court":"Utah","url":"https://www.courtlistener.com/c/P.2d/176/144/","by":{"2":"8"}},{"t":"case","label":"Fox v. Vice","cite":"563 U.S. 826","y":2011,"id":"2010/10-114","sc":1,"sum":"The Court held that a court may award attorney's fees to civil rights defendants when the plaintiff's suit involves frivolous and non-frivolous claims, but only for the costs incurred due to the frivolous claims.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Haczela v. Krupa","cite":"106 N.E. 1004","y":1914,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./106/1004/","by":{"2":"8"}},{"t":"case","label":"Norwood v. Baker","cite":"172 U.S. 269","y":1898,"id":"scdb/1898-031","sc":1,"sum":"The principle underlying special assessments upon private property to meet the cost of public improvements is that the property upon which they are imposed is peculiarly benefited, and therefore that the owners do not in fact pay anything in excess of what they receive by reason of such improvement.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"Sprague v. Ticonic Nat’l Bank","cite":"307 U.S. 161","y":1939,"id":"scdb/1938-148","sc":1,"sum":"1. When a litigant in the District Court, through the prosecution of a suit on his own behalf and at his own expense, has affixed a lien on earmarked funds in an insolvent bank for the repayment in full, with ordinary costs and interest, of a sum theretofore deposited by him in trust, and, by so doing, has incidentally, through the principle of stare decisis, established like rights for other depositors, not parties …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Trustees v. Greenough","cite":"105 U.S. 527","y":1882,"id":"scdb/1881-199","sc":1,"sum":"Stating that a statute fixing costs does not “regulate the fees of counsel and other expenses”.","sumSrc":"brief:2","by":{"2":"6"}},{"t":"case","label":"United States ex rel. Hyde v. Bancroft","cite":"24 F. Cas. 980","y":1873,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Cas./24/980/","by":{"2":"6"}},{"t":"case","label":"Wisconsin v. Hotline Indus., Inc.","cite":"236 F.3d 363","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/236/363/","by":{"2":"12"}},{"t":"usc","label":"29 U.S.C. § 187","url":"https://www.law.cornell.edu/uscode/text/29/187","subs":["(b)"],"by":{"2":"20"}},{"t":"usc","label":"40 U.S.C. § 270b","url":"https://www.law.cornell.edu/uscode/text/40/270b","subs":["(a)(1970)"],"by":{"2":"20"}},{"t":"usc","label":"42 U.S.C. § 4654","url":"https://www.law.cornell.edu/uscode/text/42/4654","subs":["(a)"],"by":{"2":"7"}},{"t":"usc","label":"42 U.S.C. § 9607","url":"https://www.law.cornell.edu/uscode/text/42/9607","subs":["(a)(4)(B)"],"by":{"2":"20"}}]};